351	static void pet_save(void)
352	{
353	    char tmp_path[64];
354	    snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", PET_SAVE_PATH);
355	
356	    FILE *f = fopen(tmp_path, "w");
357	    if (!f) return;
358	    fprintf(f,
359	        "{\"version\":%d,\"pet_type\":%d,\"name\":\"%s\","
360	        "\"hunger\":%d,\"energy\":%d,\"happiness\":%d,"
361	        "\"affection\":%d,\"health\":%d,\"growth\":%d,"
362	        "\"last_interaction\":%ld,\"last_update\":%ld,"
363	        "\"created_at\":%ld,\"total_days\":%d}\n",
364	        1, g_pet.pet_type, g_pet.name,
365	        g_pet.attrs.hunger, g_pet.attrs.energy, g_pet.attrs.happiness,
366	        g_pet.attrs.affection, g_pet.attrs.health, g_pet.attrs.growth,
367	        g_pet.last_interaction, g_pet.last_update,
368	        g_pet.created_at, g_pet.total_days);
369	    fflush(f);
370	    fsync(fileno(f));
371	    fclose(f);
372	    rename(tmp_path, PET_SAVE_PATH);
373	}
