375	static void pet_load(void)
376	{
377	    FILE *f = fopen(PET_SAVE_PATH, "r");
378	    if (!f)
379	    {
380	        /* 首次运行：默认猫 + "旺财" */
381	        memset(&g_pet, 0, sizeof(g_pet));
382	        g_pet.version   = 1;
383	        g_pet.pet_type  = PET_TYPE_CAT;
384	        strcpy(g_pet.name, "旺财");
385	        g_pet.attrs.hunger    = 50;
386	        g_pet.attrs.energy    = 80;
387	        g_pet.attrs.happiness = 60;
388	        g_pet.attrs.affection = 20;
389	        g_pet.attrs.health    = 100;
390	        g_pet.attrs.growth    = 0;
391	        g_pet.last_interaction = time(NULL);
392	        g_pet.last_update      = time(NULL);
393	        g_pet.created_at       = time(NULL);
