402	        "\"affection\":%d,\"health\":%d,\"growth\":%d,"
403	        "\"last_interaction\":%ld,\"last_update\":%ld,"
404	        "\"created_at\":%ld,\"total_days\":%d",
405	        &g_pet.version, (int *)&g_pet.pet_type, g_pet.name,
406	        &g_pet.attrs.hunger, &g_pet.attrs.energy, &g_pet.attrs.happiness,
407	        &g_pet.attrs.affection, &g_pet.attrs.health, &g_pet.attrs.growth,
408	        &g_pet.last_interaction, &g_pet.last_update,
409	        &g_pet.created_at, &g_pet.total_days);
