411	
412	    /* 离线时间计算：关机期间属性缓慢变化 */
413	    time_t now = time(NULL);
414	    long elapsed_h = (now - g_pet.last_update) / 3600;
415	    if (elapsed_h > 0 && elapsed_h < 720)  /* 最多算30天 */
416	    {
417	        int hunger_rate = (g_pet.pet_type == PET_TYPE_DOG) ? 2 : 1;
418	        g_pet.attrs.hunger     = clamp(g_pet.attrs.hunger + hunger_rate * elapsed_h, 0, 100);
419	        /* 离线恢复精力：每天最多 +12（≈半天睡眠），防止长离线免费满血 */
420	        long energy_gain = elapsed_h / 2;
421	        if (energy_gain > 12 * (elapsed_h / 24 + 1))
422	            energy_gain = 12 * (elapsed_h / 24 + 1);
423	        g_pet.attrs.energy     = clamp(g_pet.attrs.energy + energy_gain, 0, 100);
