425	        if (g_pet.attrs.hunger < 20)
426	            g_pet.attrs.health = clamp(g_pet.attrs.health - elapsed_h, PET_HEALTH_FLOOR, 100);
427	        g_pet.total_days += elapsed_h / 24;
428	    }
429	    g_pet.last_update = now;
430	
