452	               acc_sleep = 0;
453	
454	    int hunger_rate = (g_pet.pet_type == PET_TYPE_DOG) ? 2 : 1;
455	
456	    acc_hunger += hunger_rate;
457	    acc_energy += PET_ENERGY_DECAY;
458	    acc_happy  += PET_HAPPINESS_DECAY;
459	    if (g_state == PET_STATE_SLEEP)
460	        acc_sleep += PET_ENERGY_SLEEP_RECOVER;
461	
462	    if (acc_hunger >= 60) { g_pet.attrs.hunger = clamp(g_pet.attrs.hunger + 1, 0, 100); acc_hunger -= 60; }
463	    if (acc_energy >= 120) { g_pet.attrs.energy = clamp(g_pet.attrs.energy - 1, 0, 100); acc_energy -= 120; }
464	    if (acc_happy >= 600) { g_pet.attrs.happiness = clamp(g_pet.attrs.happiness - 3, 0, 100); acc_happy -= 600; }
465	    if (acc_sleep >= 3) { g_pet.attrs.energy = clamp(g_pet.attrs.energy + 1, 0, 100); acc_sleep -= 3; }
466	
467	    /* 健康间接衰减：hunger<20 每分钟 -1/60（每小时 -1） */
468	    if (g_pet.attrs.hunger < 20)
469	    {
470	        acc_health += 1;
471	        if (acc_health >= 60)
472	        {
473	            g_pet.attrs.health = clamp(g_pet.attrs.health - 1, PET_HEALTH_FLOOR, 100);
474	            acc_health -= 60;
475	        }
476	    }
477	
478	    g_pet.last_update = time(NULL);
