490	    if (g_state == PET_STATE_SLEEP)
491	    {
492	        if (h >= PET_WAKE_HOUR_START && h < PET_WAKE_HOUR_END &&
493	            g_pet.attrs.energy >= PET_WAKE_ENERGY_MIN)
494	            return PET_STATE_IDLE;
495	        /* 否则继续睡 */
496	        return PET_STATE_SLEEP;
