498	
499	    /* 深夜强制睡觉 */
500	    if (h >= 0 && h < 6)
501	        return PET_STATE_SLEEP;
502	
503	    /* 精力不足 → 困倦过渡（先 SLEEPY 再 SLEEP） */
504	    if (g_pet.attrs.energy < 25 && g_state != PET_STATE_SLEEPY &&
505	        g_state != PET_STATE_SLEEP)
506	        return PET_STATE_SLEEPY;
507	
508	    /* 精力耗尽 → 强制睡觉 */
509	    if (g_pet.attrs.energy < 10)
510	        return PET_STATE_SLEEP;
511	
512	    /* 饥饿 */
513	    if (g_pet.attrs.hunger > 80 && g_state != PET_STATE_EAT)
514	        return PET_STATE_HUNGRY;
515	
516	    /* 快乐极低 */
517	    if (g_pet.attrs.happiness < 20 && g_state != PET_STATE_SAD)
518	        return PET_STATE_SAD;
519	
520	    return PET_STATE_IDLE;
