578	 ****************************************************************************/
579	
580	static const pet_behavior_t *pick_from_pool(const pet_behavior_t *pool,
581	                                            int count)
582	{
583	    int total = 0;
584	    for (int i = 0; i < count; i++)
585	        total += pool[i].weight;
586	    if (total <= 0) return &pool[0];
587	
588	    int r = rand() % total;
589	    for (int i = 0; i < count; i++)
590	    {
591	        r -= pool[i].weight;
592	        if (r < 0) return &pool[i];
593	    }
594	    return &pool[count - 1];
595	}
