709	        g_pet.last_interaction = time(NULL);
710	        /* 猫可能不理你，狗一定回应 */
711	        if (g_pet.pet_type == PET_TYPE_DOG || (rand() % 3) > 0)
712	            pet_transition_to(PET_STATE_TOUCH, "tap-body");
713	        break;
714	
715	    case PET_EVT_LONG_PRESS:
716	        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 3, 0, 100);
717	        g_pet.attrs.affection = clamp(g_pet.attrs.affection + 2, 0, 100);
718	        g_pet.last_interaction = time(NULL);
719	        pet_transition_to(PET_STATE_TOUCH, "long-press");
720	        break;
721	
722	    case PET_EVT_RAPID_TAP:
723	        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 5, 0, 100);
724	        g_pet.attrs.energy = clamp(g_pet.attrs.energy - 5, 0, 100);
