732	        g_pet.last_interaction = time(NULL);
733	        pet_transition_to(PET_STATE_PLAY, "drag");
734	        break;
735	
736	    /* ── 投喂 ── */
737	    case PET_EVT_FEED_FISH:
738	    case PET_EVT_FEED_MEAT:
739	    case PET_EVT_FEED_VEGGIE:
740	    case PET_EVT_FEED_SNACK:
741	    {
742	        int fi = evt - PET_EVT_FEED_FISH;
