755	    }
756	
757	    /* ── 环境 ── */
758	    case PET_EVT_MUSIC_ON:
759	        if (g_state == PET_STATE_SLEEP) pet_wake_now();
760	        pet_transition_to(PET_STATE_HAPPY, "music-on");
761	        break;
762	
763	    case PET_EVT_MUSIC_OFF:
764	        if (g_state == PET_STATE_HAPPY)
765	            pet_transition_to(PET_STATE_IDLE, "music-off");
766	        break;
767	
768	    case PET_EVT_WEATHER_CHANGE:
769	        /* 3级：非晴天极端天气 → 单态 CURIOUS + 天气气泡；晴天无动作 */
770	        if (g_state != PET_STATE_SLEEP && param != 0) {
771	            const char *wtxt = (param == 1) ? "下雨了~"
772	                             : (param == 2) ? "好热啊…"
773	                             :               "有点冷…";
774	            pet_transition_to(PET_STATE_CURIOUS, "weather");
775	            if (g_bubble && g_bubble_lbl) {
776	                lv_label_set_text(g_bubble_lbl, wtxt);
777	                lv_obj_clear_flag(g_bubble, LV_OBJ_FLAG_HIDDEN);
778	                g_bubble_ticks = PET_BUBBLE_DURATION_TICKS;
779	            }
780	        }
781	        break;
782	
783	    case PET_EVT_VOICE_CMD:
784	        if (param == PET_EVT_FEED_FISH || param == PET_EVT_FEED_MEAT ||
785	            param == PET_EVT_FEED_VEGGIE || param == PET_EVT_FEED_SNACK)
786	        {
787	            /* 语音投喂：直接把对应食物事件入队 */
788	            dm_pet_on_event((dm_pet_event_t)(PET_EVT_FEED_FISH + (param - PET_EVT_FEED_FISH)));
789	        }
790	        else if (param == PET_EVT_RAPID_TAP)
791	        {
792	            pet_transition_to(PET_STATE_PLAY, "voice-play");
793	        }
794	        break;
795	
796	    /* ── 生命周期 ── */
797	    case PET_EVT_WAKE_UP:
798	        /* 退出锁屏/进主屏：暂停动画省 CPU */
799	        if (g_anim_timer) lv_timer_pause(g_anim_timer);
800	        if (g_behavior_timer) lv_timer_pause(g_behavior_timer);
801	        break;
802	
803	    case PET_EVT_SLEEP:
804	        /* 进入锁屏：恢复动画 + 重新停靠右下角（防 wander 残留偏移） */
805	        if (g_anim_timer) lv_timer_resume(g_anim_timer);
806	        if (g_behavior_timer) lv_timer_resume(g_behavior_timer);
807	        pet_park_bottom_right();
808	        break;
809	
810	    case PET_EVT_TIME_TICK:
811	        pet_update_attrs_tick();
812	        /* 检查是否需要状态转移（睡眠唤醒/深夜入睡/饥饿/困倦） */
813	        {
814	            dm_pet_state_t next = pet_next_state();
815	            if (next != g_state)
816	                pet_transition_to(next, "time-tick");
817	        }
818	        break;
819	
820	    default:
821	        break;
822	    }
823	
824	    /* 关键事件立即保存 */
825	    if (save_now)
826	        pet_save();
827	}
