1013	{
1014	    lv_event_stop_bubbling(e);
1015	    if (!g_press_active) return;
1016	    g_press_active = false;
1017	
1018	    uint32_t duration = lv_tick_get() - g_press_start_ms;
1019	    uint32_t now = lv_tick_get();
1020	
1021	    if (duration >= PET_LONG_PRESS_MS)
1022	    {
1023	        /* 长按 = 抚摸 */
1024	        dm_pet_on_event(PET_EVT_LONG_PRESS);
1025	    }
1026	    else
1027	    {
1028	        /* 短按 = 轻点 */
1029	        uint32_t gap = now - g_last_tap_ms;
1030	        g_last_tap_ms = now;
1031	
1032	        if (gap < PET_RAPID_TAP_WINDOW_MS)
1033	            g_rapid_tap_count++;
1034	        else
1035	            g_rapid_tap_count = 1;
1036	
1037	        if (g_rapid_tap_count >= PET_RAPID_TAP_COUNT)
1038	        {
1039	            dm_pet_on_event(PET_EVT_RAPID_TAP);
1040	            g_rapid_tap_count = 0;
1041	        }
1042	        else
1043	        {
1044	            /* 触摸分区：用屏幕绝对坐标（lv_obj_get_coords） */
1045	            lv_area_t coords;
1046	            lv_obj_get_coords(g_body, &coords);
1047	            lv_coord_t h = coords.y2 - coords.y1 + 1;
1048	            lv_indev_t *indev = lv_indev_get_act();
1049	            lv_point_t pt;
1050	            if (indev)
1051	            {
1052	                lv_indev_get_point(indev, &pt);
1053	                if (pt.y < coords.y1 + h / 3)
1054	                    dm_pet_on_event(PET_EVT_TAP_HEAD);
1055	                else
1056	                    dm_pet_on_event(PET_EVT_TAP_BODY);
1057	            }
1058	            else
1059	            {
1060	                dm_pet_on_event(PET_EVT_TAP_BODY);
1061	            }
1062	
1063	            /* 短按弹出轻量互动条 */
1064	            pet_show_interact_bar();
1065	        }
