/****************************************************************************
 * 动画帧 timer（每 PET_ANIM_TICK_MS）
 ****************************************************************************/

/* 全屏自由走动：绝对坐标定位（不用 align/translate，直接 set_pos） */
static lv_coord_t g_pet_x = 0;            /* 当前位置 x */
static lv_coord_t g_pet_y = 0;            /* 当前位置 y */
static lv_coord_t g_target_x = 0;         /* 目标位置 x */
static lv_coord_t g_target_y = 0;         /* 目标位置 y */
static bool       g_face_right = false;   /* 朝向：true=面朝右（默认面朝左） */
static int        g_walk_pause = 0;       /* 到达目标后暂停 ticks */
static lv_coord_t g_bounce_off = 0;       /* 弹跳 y 偏移 */

static void pet_pick_new_target(void)
{
    lv_coord_t sw = lv_display_get_horizontal_resolution(NULL);
    lv_coord_t sh = lv_display_get_vertical_resolution(NULL);
    /* 边距：精灵半宽64px + 上方留空给气泡80px，下方留空给名字40px */
    lv_coord_t margin_x = PET_SIZE / 2 + DM(4);
    lv_coord_t margin_top = PET_SIZE / 2 + DM(32);
    lv_coord_t margin_bot = PET_SIZE / 2 + DM(16);
    g_target_x = rand_range(margin_x, sw - margin_x);
    g_target_y = rand_range(margin_top, sh - margin_bot);
}

static void pet_park_bottom_right(void)
{
    if (!g_cont) return;
    lv_coord_t sw = lv_display_get_horizontal_resolution(NULL);
    lv_coord_t sh = lv_display_get_vertical_resolution(NULL);
    g_pet_x = sw - PET_SIZE / 2 - DM(20);
    g_pet_y = sh - PET_SIZE / 2 - DM(60);
    g_target_x = g_pet_x;
    g_target_y = g_pet_y;
    g_face_right = false;
    g_bounce_off = 0;
    g_walk_pause = rand_range(8, 20);
    lv_obj_set_pos(g_cont, g_pet_x - lv_obj_get_width(g_cont) / 2,
                   g_pet_y - lv_obj_get_height(g_cont) / 2);
    lv_obj_move_foreground(g_cont);
}

