/* ── 全屏自由走动 ── */
g_bounce_off = 0;
if (g_state == PET_STATE_IDLE || g_state == PET_STATE_HAPPY ||
    g_state == PET_STATE_SAD || g_state == PET_STATE_HUNGRY ||
    g_state == PET_STATE_CURIOUS)
{
    /* 到达目标 → 暂停 → 选新目标 */
    int dx = g_target_x - g_pet_x;
    int dy = g_target_y - g_pet_y;
    int dist_sq = dx * dx + dy * dy;

    if (dist_sq < 16)  /* 到达（4px内） */
    {
        if (g_walk_pause > 0)
            g_walk_pause--;
        else
            pet_pick_new_target();
    }
    else
    {
        /* 步进：每 tick 移2px，朝目标方向 */
        int step = 2;
        if (dist_sq > 2500) step = 3;  /* 距离远时加速 */
        int len = (int)sqrt((double)dist_sq);
        if (len > 0)
        {
            g_pet_x += (lv_coord_t)((long)dx * step / len);
            g_pet_y += (lv_coord_t)((long)dy * step / len);
        }
        /* 朝向：跟随移动方向 */
        if (dx > 1)  g_face_right = true;
        else if (dx < -1) g_face_right = false;
    }

    /* 边缘安全钳位 */
    lv_coord_t sw = lv_display_get_horizontal_resolution(NULL);
    lv_coord_t sh = lv_display_get_vertical_resolution(NULL);
    lv_coord_t mx = PET_SIZE / 2 + DM(4);
    lv_coord_t myt = PET_SIZE / 2 + DM(32);
    lv_coord_t myb = PET_SIZE / 2 + DM(16);
    if (g_pet_x < mx)    { g_pet_x = mx;    pet_pick_new_target(); }
    if (g_pet_x > sw-mx)  { g_pet_x = sw-mx;  pet_pick_new_target(); }
    if (g_pet_y < myt)   { g_pet_y = myt;   pet_pick_new_target(); }
    if (g_pet_y > sh-myb) { g_pet_y = sh-myb; pet_pick_new_target(); }
}
else if (g_state == PET_STATE_PLAY)
{
    g_bounce_off = (g_tick % 2) ? -10 : 10;
}
else if (g_state == PET_STATE_CELEBRATE)
{
    g_bounce_off = (g_tick % 2) ? -16 : 16;
}

/* 精灵水平翻转：面朝右 = scale_x 负值（LVGL 9 用 style_transform_scale_x） */
if (g_body)
{
    lv_obj_set_style_transform_scale_x(g_body, g_face_right ? -256 : 256, 0);
}

/* 应用位置（容器中心对齐到 g_pet_x, g_pet_y） */
lv_obj_set_pos(g_cont, g_pet_x - lv_obj_get_width(g_cont) / 2,
               g_pet_y - lv_obj_get_height(g_cont) / 2 + g_bounce_off);

